<?php use App\Services\SchoolRequestService as S; $badge = ['pending' => 'warning', 'approved' => 'success', 'rejected' => 'secondary']; $gp = ['mixed' => 'مختلطة', 'boys' => 'بنين', 'girls' => 'بنات']; ?>
<div class="d-flex flex-wrap gap-2 mb-3"><?php foreach (['' => 'الكل'] + S::STATUSES as $k => $l): ?><a class="badge text-bg-<?= $status === (string)$k ? 'primary' : 'secondary' ?> text-decoration-none fs-6" href="<?= url('platform/requests' . ($k ? '?status=' . $k : '')) ?>"><?= e($l) ?></a><?php endforeach; ?></div>
<div data-result></div>
<?php if (!$rows): ?><div class="card-s empty-state"><i class="bi bi-inbox"></i>لا توجد طلبات.</div><?php endif; ?>
<?php foreach ($rows as $x): ?><div class="card-s mb-3"><div class="d-flex flex-wrap gap-3 align-items-start">
 <?php if ($x['logo_file']): ?><img src="<?= url('platform/requests/' . (int)$x['id'] . '/logo') ?>" alt="شعار" style="width:72px;height:72px;object-fit:contain" class="border rounded p-1 bg-white"><?php endif; ?>
 <div class="flex-grow-1"><div class="d-flex flex-wrap gap-2 align-items-center"><h2 class="h6 mb-0"><?= e($x['school_name']) ?></h2><span class="badge text-bg-<?= $badge[$x['status']] ?>"><?= e(S::STATUSES[$x['status']]) ?></span><small class="text-muted">#<?= (int)$x['id'] ?> · <?= e(substr((string)$x['created_at'], 0, 16)) ?></small></div>
  <dl class="row small mb-0 mt-2"><dt class="col-sm-2">المسؤول</dt><dd class="col-sm-10"><?= e($x['contact_name']) ?> — <span dir="ltr"><?= e($x['contact_email']) ?></span> <span dir="ltr"><?= e($x['contact_phone'] ?? '') ?></span></dd>
  <dt class="col-sm-2">الموقع</dt><dd class="col-sm-10"><?= e(trim(($x['governorate'] ?? '') . ' ' . ($x['city'] ?? '') . ' ' . ($x['address'] ?? ''))) ?: '—' ?></dd><dt class="col-sm-2">التفاصيل</dt><dd class="col-sm-10"><?= e($gp[$x['gender_policy']]) ?> · <?= e($x['stages'] ?? '—') ?> · طلاب: <?= $x['students_estimate'] ? (int)$x['students_estimate'] : '—' ?></dd>
  <?php if ($x['notes']): ?><dt class="col-sm-2">ملاحظات</dt><dd class="col-sm-10"><?= e($x['notes']) ?></dd><?php endif; ?>
  <?php if ($x['status'] !== 'pending'): ?><dt class="col-sm-2">القرار</dt><dd class="col-sm-10"><?= e($x['decided_name'] ?? '') ?> <?= e(substr((string)$x['decided_at'], 0, 16)) ?><?= $x['decision_note'] ? ' — ' . e($x['decision_note']) : '' ?><?= $x['school_id'] ? ' — <a href="' . e(url('platform/schools/' . (int)$x['school_id'])) . '">فتح المدرسة</a>' : '' ?></dd><?php endif; ?></dl></div></div>
 <?php if ($x['status'] === 'pending'): ?><hr><div class="row g-2 align-items-end"><form class="col-lg-8 row g-2 align-items-end" method="post" action="<?= url('api/v1/platform/requests/' . (int)$x['id'] . '/approve') ?>" data-ajax data-reload-after novalidate><?= csrf_field() ?>
  <div class="col-md-5"><label class="form-label small" for="n<?= (int)$x['id'] ?>">اسم المدرسة (تعديل اختياري)</label><input class="form-control" id="n<?= (int)$x['id'] ?>" name="school_name" value="<?= e($x['school_name']) ?>"></div>
  <div class="col-md-4"><label class="form-label small" for="p<?= (int)$x['id'] ?>">خطة الاشتراك *</label><select class="form-select" id="p<?= (int)$x['id'] ?>" name="plan_id" required><option value="">اختر</option><?php foreach ($plans as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-3"><button class="btn btn-success w-100"><i class="bi bi-check-lg"></i> قبول</button></div></form>
  <div class="col-lg-4"><button class="btn btn-outline-danger w-100" data-api="<?= url('api/v1/platform/requests/' . (int)$x['id'] . '/reject') ?>" data-prompt="سبب الرفض (يُرسل للمتقدّم)" data-prompt-field="note"><i class="bi bi-x-lg"></i> رفض</button></div></div><?php endif; ?></div><?php endforeach; ?>
